def count_distinct_photos(n, m, board):
    # Helper function to check if two cells are connected
    def is_connected(cell1, cell2):
        if cell1[0] == cell2[0]:  # Same row
            return abs(cell1[1] - cell2[1]) == 1
        elif cell1[1] == cell2[1]:  # Same column
            return abs(cell1[0] - cell2[0]) == 1
        return False

    # Generate all possible pairs of free cells
    free_cells = []
    for i in range(n):
        for j in range(m):
            if board[i][j] == 'U' and i % 2 == 0:
                free_cells.append((i, j))
            elif board[i][j] == 'D' and i % 2 == 1:
                free_cells.append((i, j))
            elif board[i][j] == 'L' and j % 2 == 0:
                free_cells.append((i, j))
            elif board[i][j] == 'R' and j % 2 == 1:
                free_cells.append((i, j))

    # Use a set to store unique pairs of free cells
    unique_photos = set()

    # Check all pairs of free cells
    for i in range(len(free_cells)):
        for j in range(i + 1, len(free_cells)):
            if is_connected(free_cells[i], free_cells[j]):
                unique_photos.add((free_cells[i], free_cells[j]))

    return len(unique_photos)

